def czy_mniejszy(n, s, k1, k2):
    i, j = k1, k2
    while i <= n and j <= n:
        if s[i-1] == s[j-1]:
            i += 1
            j += 1
        else:
            return s[i-1] < s[j-1]
    return j <= n

def najmniejszy_sufiks(n, s):
    best = 1
    for k in range(2, n+1):
        if czy_mniejszy(n, s, k, best):
            best = k
    return s[best-1:]

with open('slowa4.txt', encoding='utf-8') as f:
    for w in f:
        n_str, s = w.strip().split(' ', 1)
        print(najmniejszy_sufiks(int(n_str), s))

